-- DCP Pulse: integrity constraints, triggers, tenant row-level security and grants.
-- Hand-written (not generated by Prisma). Objects here are CHECKs, triggers,
-- functions, policies and grants, which Prisma does not model.

-- ---------------------------------------------------------------------------
-- Tenant context
-- ---------------------------------------------------------------------------
-- The API sets `app.tenant_id` transaction-locally (set_config(..., true)).
-- Missing/empty context resolves to NULL, so RLS denies by default.
CREATE FUNCTION app_current_tenant() RETURNS uuid
  LANGUAGE sql STABLE
  AS $$ SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid $$;

-- ---------------------------------------------------------------------------
-- CHECK constraints
-- ---------------------------------------------------------------------------
ALTER TABLE budget_versions     ADD CONSTRAINT budget_versions_amount_non_negative     CHECK (total_amount >= 0),
                                ADD CONSTRAINT budget_versions_currency_code_format    CHECK (currency_code ~ '^[A-Z]{3}$'),
                                ADD CONSTRAINT budget_versions_scheme_or_envelope      CHECK (scheme_id IS NOT NULL OR jurisdiction_id IS NOT NULL),
                                ADD CONSTRAINT budget_versions_version_number_positive CHECK (version_number >= 1),
                                ADD CONSTRAINT budget_versions_approved_has_metadata   CHECK (status <> 'APPROVED' OR approved_at IS NOT NULL);
ALTER TABLE budget_requests     ADD CONSTRAINT budget_requests_amount_non_negative     CHECK (amount >= 0),
                                ADD CONSTRAINT budget_requests_currency_code_format    CHECK (currency_code ~ '^[A-Z]{3}$');
ALTER TABLE budget_allocations  ADD CONSTRAINT budget_allocations_amount_non_negative  CHECK (amount >= 0),
                                ADD CONSTRAINT budget_allocations_currency_code_format CHECK (currency_code ~ '^[A-Z]{3}$'),
                                ADD CONSTRAINT budget_allocations_not_own_parent       CHECK (parent_allocation_id IS DISTINCT FROM id);
ALTER TABLE fund_releases       ADD CONSTRAINT fund_releases_amount_non_negative       CHECK (amount >= 0),
                                ADD CONSTRAINT fund_releases_currency_code_format      CHECK (currency_code ~ '^[A-Z]{3}$'),
                                ADD CONSTRAINT fund_releases_correction_has_reason     CHECK (supersedes_id IS NULL OR (supersedes_id <> id AND length(btrim(correction_reason)) > 0));
ALTER TABLE commitments         ADD CONSTRAINT commitments_amount_non_negative         CHECK (amount >= 0),
                                ADD CONSTRAINT commitments_currency_code_format        CHECK (currency_code ~ '^[A-Z]{3}$');
ALTER TABLE expenditure_records ADD CONSTRAINT expenditure_records_amount_non_negative CHECK (amount >= 0),
                                ADD CONSTRAINT expenditure_records_currency_code_format CHECK (currency_code ~ '^[A-Z]{3}$'),
                                ADD CONSTRAINT expenditure_records_correction_has_reason CHECK (supersedes_id IS NULL OR (supersedes_id <> id AND length(btrim(correction_reason)) > 0)),
                                ADD CONSTRAINT expenditure_records_verified_has_verifier CHECK (status <> 'VERIFIED' OR (verified_by IS NOT NULL AND verified_at IS NOT NULL)),
                                -- Maker-checker defence in depth: the submitter can never be the verifier.
                                ADD CONSTRAINT expenditure_records_maker_checker        CHECK (verified_by IS NULL OR verified_by IS DISTINCT FROM submitted_by);

ALTER TABLE jurisdictions       ADD CONSTRAINT jurisdictions_not_own_parent            CHECK (parent_id IS DISTINCT FROM id);
ALTER TABLE scheme_milestones   ADD CONSTRAINT scheme_milestones_weight_range          CHECK (weight >= 0 AND weight <= 100),
                                ADD CONSTRAINT scheme_milestones_target_quantity_non_negative CHECK (target_quantity >= 0);
ALTER TABLE progress_measurements ADD CONSTRAINT progress_measurements_quantity_non_negative CHECK (quantity_completed >= 0),
                                ADD CONSTRAINT progress_measurements_percent_range     CHECK (reported_percent IS NULL OR (reported_percent >= 0 AND reported_percent <= 100));
ALTER TABLE progress_submissions ADD CONSTRAINT progress_submissions_version_positive  CHECK (submission_version >= 1),
                                ADD CONSTRAINT progress_submissions_not_own_correction CHECK (supersedes_id IS DISTINCT FROM id);
ALTER TABLE financial_years     ADD CONSTRAINT financial_years_date_order              CHECK (end_date > start_date);
ALTER TABLE reporting_periods   ADD CONSTRAINT reporting_periods_date_order            CHECK (end_date >= start_date);
ALTER TABLE schemes             ADD CONSTRAINT schemes_date_order                      CHECK (target_end_date IS NULL OR start_date IS NULL OR target_end_date >= start_date);
ALTER TABLE agency_jurisdictions ADD CONSTRAINT agency_jurisdictions_date_order        CHECK (effective_to IS NULL OR effective_to >= effective_from);
ALTER TABLE user_role_scopes    ADD CONSTRAINT user_role_scopes_date_order             CHECK (valid_to IS NULL OR valid_to > valid_from),
                                ADD CONSTRAINT user_role_scopes_tenant_scope_is_tenant CHECK (scope_type <> 'TENANT' OR scope_id = tenant_id);
ALTER TABLE alert_rules         ADD CONSTRAINT alert_rules_date_order                  CHECK (effective_to IS NULL OR effective_to >= effective_from);
ALTER TABLE evidence_files      ADD CONSTRAINT evidence_files_size_non_negative        CHECK (size_bytes >= 0);
ALTER TABLE users               ADD CONSTRAINT users_email_lowercase                   CHECK (email = lower(email));

-- ---------------------------------------------------------------------------
-- Jurisdiction ancestry and cycle prevention
-- ---------------------------------------------------------------------------
CREATE FUNCTION jurisdictions_set_ancestry() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  parent_ancestry uuid[];
BEGIN
  IF NEW.parent_id IS NULL THEN
    NEW.ancestry := '{}';
    RETURN NEW;
  END IF;

  SELECT ancestry INTO parent_ancestry
    FROM jurisdictions WHERE id = NEW.parent_id AND tenant_id = NEW.tenant_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'JURISDICTION_PARENT_NOT_FOUND' USING ERRCODE = '23503';
  END IF;
  IF NEW.id = NEW.parent_id OR NEW.id = ANY (parent_ancestry) THEN
    RAISE EXCEPTION 'JURISDICTION_CYCLE: % cannot be placed under its own descendant', NEW.id
      USING ERRCODE = '23514';
  END IF;

  NEW.ancestry := parent_ancestry || NEW.parent_id;
  RETURN NEW;
END $$;

CREATE TRIGGER jurisdictions_set_ancestry
  BEFORE INSERT OR UPDATE OF parent_id, ancestry ON jurisdictions
  FOR EACH ROW EXECUTE FUNCTION jurisdictions_set_ancestry();

-- When a node's ancestry changes, touch its direct children so their ancestry is
-- recomputed; this recurses down the subtree.
CREATE FUNCTION jurisdictions_propagate_ancestry() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jurisdictions SET ancestry = ancestry
   WHERE parent_id = NEW.id AND tenant_id = NEW.tenant_id;
  RETURN NULL;
END $$;

CREATE TRIGGER jurisdictions_propagate_ancestry
  AFTER UPDATE OF parent_id, ancestry ON jurisdictions
  FOR EACH ROW WHEN (OLD.ancestry IS DISTINCT FROM NEW.ancestry)
  EXECUTE FUNCTION jurisdictions_propagate_ancestry();

-- ---------------------------------------------------------------------------
-- Budget: one approved version per scheme; allocation ceilings
-- ---------------------------------------------------------------------------
CREATE UNIQUE INDEX budget_versions_one_approved_per_scheme
  ON budget_versions (tenant_id, scheme_id)
  WHERE status = 'APPROVED' AND scheme_id IS NOT NULL;

-- Approved allocations may not exceed their ceiling: the approved budget
-- version total for top-level allocations, or the approved parent allocation
-- for child allocations. The ceiling row is locked FOR UPDATE, so concurrent
-- writers under the same ceiling are serialised and cannot over-allocate.
CREATE FUNCTION budget_allocations_enforce_ceiling() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  ceiling        numeric(18, 2);
  already        numeric(18, 2);
  ceiling_status text;
  parent_version uuid;
BEGIN
  IF NEW.status <> 'APPROVED' THEN
    RETURN NEW;
  END IF;

  IF NEW.parent_allocation_id IS NULL THEN
    SELECT total_amount, status::text INTO ceiling, ceiling_status
      FROM budget_versions
     WHERE id = NEW.budget_version_id AND tenant_id = NEW.tenant_id
       FOR UPDATE;
    IF ceiling_status IS DISTINCT FROM 'APPROVED' THEN
      RAISE EXCEPTION 'ALLOCATION_REQUIRES_APPROVED_BUDGET_VERSION' USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(SUM(amount), 0) INTO already
      FROM budget_allocations
     WHERE tenant_id = NEW.tenant_id AND budget_version_id = NEW.budget_version_id
       AND parent_allocation_id IS NULL AND status = 'APPROVED' AND id <> NEW.id;
  ELSE
    SELECT amount, status::text, budget_version_id INTO ceiling, ceiling_status, parent_version
      FROM budget_allocations
     WHERE id = NEW.parent_allocation_id AND tenant_id = NEW.tenant_id
       FOR UPDATE;
    IF ceiling_status IS DISTINCT FROM 'APPROVED' THEN
      RAISE EXCEPTION 'ALLOCATION_REQUIRES_APPROVED_PARENT' USING ERRCODE = '23514';
    END IF;
    IF parent_version <> NEW.budget_version_id THEN
      RAISE EXCEPTION 'ALLOCATION_PARENT_VERSION_MISMATCH' USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(SUM(amount), 0) INTO already
      FROM budget_allocations
     WHERE tenant_id = NEW.tenant_id AND parent_allocation_id = NEW.parent_allocation_id
       AND status = 'APPROVED' AND id <> NEW.id;
  END IF;

  IF already + NEW.amount > ceiling THEN
    RAISE EXCEPTION 'ALLOCATION_CEILING_EXCEEDED: allocated % + requested % > ceiling %',
      already, NEW.amount, ceiling USING ERRCODE = '23514';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    SELECT COALESCE(SUM(amount), 0) INTO already
      FROM budget_allocations
     WHERE tenant_id = NEW.tenant_id AND parent_allocation_id = NEW.id AND status = 'APPROVED';
    IF already > NEW.amount THEN
      RAISE EXCEPTION 'ALLOCATION_BELOW_CHILD_TOTAL: children % > amount %', already, NEW.amount
        USING ERRCODE = '23514';
    END IF;
  END IF;

  RETURN NEW;
END $$;

CREATE TRIGGER budget_allocations_enforce_ceiling
  BEFORE INSERT OR UPDATE ON budget_allocations
  FOR EACH ROW EXECUTE FUNCTION budget_allocations_enforce_ceiling();

CREATE FUNCTION budget_versions_protect_allocated_total() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  already numeric(18, 2);
BEGIN
  SELECT COALESCE(SUM(amount), 0) INTO already
    FROM budget_allocations
   WHERE tenant_id = NEW.tenant_id AND budget_version_id = NEW.id
     AND parent_allocation_id IS NULL AND status = 'APPROVED';
  IF already > NEW.total_amount THEN
    RAISE EXCEPTION 'BUDGET_VERSION_BELOW_ALLOCATED: allocated % > total %', already, NEW.total_amount
      USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER budget_versions_protect_allocated_total
  BEFORE UPDATE OF total_amount ON budget_versions
  FOR EACH ROW EXECUTE FUNCTION budget_versions_protect_allocated_total();

-- ---------------------------------------------------------------------------
-- Verified facts are immutable; corrections are superseding records
-- ---------------------------------------------------------------------------
CREATE FUNCTION prevent_verified_mutation() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(OLD) ->> TG_ARGV[0]) = 'VERIFIED' THEN
    RAISE EXCEPTION 'VERIFIED_RECORD_IMMUTABLE: %.% is verified; record a superseding correction instead',
      TG_TABLE_NAME, OLD.id USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER expenditure_records_verified_immutable
  BEFORE UPDATE OR DELETE ON expenditure_records
  FOR EACH ROW EXECUTE FUNCTION prevent_verified_mutation('status');
CREATE TRIGGER fund_releases_verified_immutable
  BEFORE UPDATE OR DELETE ON fund_releases
  FOR EACH ROW EXECUTE FUNCTION prevent_verified_mutation('verification_status');
CREATE TRIGGER progress_submissions_verified_immutable
  BEFORE UPDATE OR DELETE ON progress_submissions
  FOR EACH ROW EXECUTE FUNCTION prevent_verified_mutation('status');

CREATE FUNCTION progress_measurements_lock_verified() RETURNS trigger
  LANGUAGE plpgsql AS $$
DECLARE
  sub_id uuid := CASE WHEN TG_OP = 'INSERT' THEN NEW.submission_id ELSE OLD.submission_id END;
BEGIN
  IF EXISTS (SELECT 1 FROM progress_submissions WHERE id = sub_id AND status = 'VERIFIED') THEN
    RAISE EXCEPTION 'VERIFIED_RECORD_IMMUTABLE: measurements of verified submission % cannot change', sub_id
      USING ERRCODE = '55000';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER progress_measurements_lock_verified
  BEFORE INSERT OR UPDATE OR DELETE ON progress_measurements
  FOR EACH ROW EXECUTE FUNCTION progress_measurements_lock_verified();

-- ---------------------------------------------------------------------------
-- Append-only business audit trail
-- ---------------------------------------------------------------------------
CREATE FUNCTION audit_events_append_only() RETURNS trigger
  LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'AUDIT_EVENTS_APPEND_ONLY: % is not permitted on audit_events', TG_OP
    USING ERRCODE = '55000';
END $$;

CREATE TRIGGER audit_events_no_update_delete
  BEFORE UPDATE OR DELETE ON audit_events
  FOR EACH ROW EXECUTE FUNCTION audit_events_append_only();
CREATE TRIGGER audit_events_no_truncate
  BEFORE TRUNCATE ON audit_events
  FOR EACH STATEMENT EXECUTE FUNCTION audit_events_append_only();

-- ---------------------------------------------------------------------------
-- Application role, grants and row-level security
-- ---------------------------------------------------------------------------
-- `dcp_app` is the runtime role (non-owner, subject to RLS). Its LOGIN and
-- password are managed outside migrations by scripts/bootstrap-db-roles.ts.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dcp_app') THEN
    CREATE ROLE dcp_app NOLOGIN;
  END IF;
END $$;

GRANT USAGE ON SCHEMA public TO dcp_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO dcp_app;
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON tenants, permissions, spatial_ref_sys FROM dcp_app;
REVOKE UPDATE, DELETE, TRUNCATE ON audit_events FROM dcp_app;
-- Read-only access to migration history for the readiness check. The table is
-- absent when Prisma replays migrations into a shadow database.
DO $$
BEGIN
  IF to_regclass('public._prisma_migrations') IS NOT NULL THEN
    REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON _prisma_migrations FROM dcp_app;
  END IF;
END $$;

DO $$
DECLARE
  t text;
BEGIN
  FOR t IN
    SELECT c.table_name
      FROM information_schema.columns c
      JOIN information_schema.tables tb
        ON tb.table_schema = c.table_schema AND tb.table_name = c.table_name
     WHERE c.table_schema = 'public' AND c.column_name = 'tenant_id' AND tb.table_type = 'BASE TABLE'
  LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I TO dcp_app USING (tenant_id = app_current_tenant()) WITH CHECK (tenant_id = app_current_tenant())',
      t);
  END LOOP;
END $$;

ALTER TABLE tenants ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_self_read ON tenants FOR SELECT TO dcp_app USING (id = app_current_tenant());
